function Chat() {
  const [threads, setThreads] = useState(demoThreads)
  const [active, setActive] = useState('demo-1')
  const [messages, setMessages] = useState(demoMessages)
  const [input, setInput] = useState('')
  const [thinking, setThinking] = useState(false)
  const endRef = useRef(null)
  useEffect(() => { request('/mental-health/threads').then(data => { if (data.threads?.length) { setThreads(data.threads); setActive(data.threads[0].id) } }).catch(() => {}) }, [])
  useEffect(() => { endRef.current?.scrollIntoView({ behavior: 'smooth' }) }, [messages, thinking])
  const send = async (event) => {
    event?.preventDefault(); const content = input.trim(); if (!content || thinking) return
    setInput(''); setMessages(prev => [...prev, { id: `u-${Date.now()}`, is_user: true, content }]); setThinking(true)
    let streamed = ''
    try {
      const token = localStorage.getItem('zen-token')
      const response = await fetch(`${API_URL}/mental-health/chat/stream`, { method: 'POST', headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${token || ''}` }, body: JSON.stringify({ message: content, thread_id: active.startsWith('demo') ? null : active }) })
      if (!response.ok || !response.body) throw new Error('offline')
      const reader = response.body.getReader(); const decoder = new TextDecoder()
      while (true) { const { done, value } = await reader.read(); if (done) break; for (const line of decoder.decode(value).split('\n')) { if (!line.startsWith('data: ')) continue; const eventData = JSON.parse(line.slice(6)); if (eventData.type === 'token') streamed += eventData.data; if (eventData.type === 'thread_id') setActive(eventData.data) } }
      setMessages(prev => [...prev, { id: `a-${Date.now()}`, is_user: false, content: streamed || 'I am here with you. Let us take this one breath at a time.' }])
    } catch { setTimeout(() => setMessages(prev => [...prev, { id: `a-${Date.now()}`, is_user: false, content: fallbackReply(content) }]), 450) }
    finally { setTimeout(() => setThinking(false), 500) }
  }
  return <div className="fade-up grid gap-5 xl:grid-cols-[280px_1fr]"><div className="panel hidden rounded-3xl p-4 xl:block"><button onClick={() => { setActive(`new-${Date.now()}`); setMessages([]) }} className="btn-primary mb-5 flex w-full items-center justify-center gap-2 text-sm"><Plus className="h-4 w-4" /> New conversation</button><div className="eyebrow px-2">recent threads</div><div className="mt-3 space-y-1">{threads.map(thread => <button key={thread.id} onClick={() => { setActive(thread.id); if (thread.id.startsWith('demo')) setMessages(demoMessages) }} className={`w-full rounded-xl p-3 text-left ${active === thread.id ? 'bg-[#2a1d43]' : 'hover:bg-[#211737]'}`}><div className="truncate text-sm font-semibold">{thread.title}</div><div className="mt-1 truncate text-xs text-[#847a99]">{thread.last_message}</div></button>)}</div><div className="mt-8 rounded-2xl border border-[#3a2b57] p-4"><ShieldCheck className="h-5 w-5 text-mint" /><div className="mt-3 text-xs font-semibold">A private space</div><p className="mt-2 text-[11px] leading-5 text-[#847a99]">Your conversations are designed to stay yours.</p></div></div><div className="panel flex min-h-[640px] flex-col rounded-3xl"><div className="flex items-center justify-between border-b border-white/[.08] px-5 py-4"><div className="flex items-center gap-3"><div className="pulse-ring flex h-10 w-10 items-center justify-center rounded-2xl bg-violet-300/15 text-violet-200"><Brain className="h-5 w-5" /></div><div><div className="font-semibold">Calm, your companion</div><div className="mt-1 flex items-center gap-2 text-xs text-[#83e7bb]"><span className="status-dot" /> here when you need me</div></div></div><IconButton label="Chat settings"><Settings className="h-4 w-4" /></IconButton></div><div className="scrollbar flex-1 space-y-5 overflow-y-auto p-5 sm:p-8">{messages.length === 0 && <div className="mx-auto mt-16 max-w-sm text-center"><div className="mx-auto flex h-14 w-14 items-center justify-center rounded-2xl bg-violet-300/10 text-violet-200"><MessageCircle /></div><h3 className="mt-5 text-xl font-bold">What is on your mind?</h3><p className="mt-2 text-sm leading-6 text-[#9d91b7]">You can start anywhere. No need to make it sound a certain way.</p></div>}{messages.map(message => <div key={message.id} className={`flex gap-3 ${message.is_user ? 'justify-end' : ''}`}><div className={`max-w-[82%] rounded-2xl px-4 py-3 text-sm leading-7 ${message.is_user ? 'rounded-br-sm bg-violet-400 text-ink' : 'rounded-bl-sm bg-[#211737] text-[#eee6ff]'}`}>{message.content}</div></div>)}{thinking && <div className="flex items-center gap-3"><div className="rounded-2xl rounded-bl-sm bg-[#211737] px-4 py-3 text-sm text-[#9d91b7]"><span className="mr-1 inline-block animate-bounce">·</span><span className="mr-1 inline-block animate-bounce [animation-delay:.1s]">·</span><span className="inline-block animate-bounce [animation-delay:.2s]">·</span></div><span className="text-xs text-[#847a99]">taking a moment</span></div>}<div ref={endRef} /></div><form onSubmit={send} className="border-t border-white/[.08] p-4"><div className="flex items-center gap-2 rounded-2xl border border-[#3a2b57] bg-[#120d20] p-2 focus-within:border-violet-300/60"><IconButton label="Voice input"><Mic2 className="h-4 w-4" /></IconButton><input value={input} onChange={e => setInput(e.target.value)} className="flex-1 bg-transparent px-2 text-sm text-white outline-none placeholder:text-[#625477]" placeholder="Share what is here…" /><button aria-label="Send message" className="rounded-xl bg-violet-300 p-2.5 text-ink transition hover:bg-violet-200"><Send className="h-4 w-4" /></button></div><div className="mt-3 text-center text-[10px] text-[#625477]">Calm is an AI companion, not a replacement for professional care.</div></form></div></div>
}
function fallbackReply(message) { if (/sad|lonely|heavy|low/i.test(message)) return 'That sounds like a lot to hold. You do not have to carry the whole feeling at once — what would make the next ten minutes a little kinder?'; if (/stress|anxious|panic|overwhelm/i.test(message)) return 'Let us make this moment smaller. Unclench your jaw, lower your shoulders, and name one thing you can set down for now.'; return 'Thank you for putting that into words. I am here with you — would you like to explore what you need, or simply be heard for a moment?' }

function Journal() {
  const [entries, setEntries] = useState([]); const [prompts, setPrompts] = useState([]); const [content, setContent] = useState(''); const [mood, setMood] = useState(''); const [saving, setSaving] = useState(false); const [saved, setSaved] = useState(false)
  useEffect(() => { request('/journal/entries').then(setEntries).catch(() => setEntries([{ _id: 'demo-j', title: 'A softer definition of enough', content: 'I’m learning that rest is not a reward for finishing everything. It is part of how I keep going.', mood: 'hopeful', tags: ['rest', 'perspective'], created_at: new Date().toISOString() }])); request('/journal/prompts').then(setPrompts).catch(() => setPrompts([{ prompt: 'What is one small win you had today?', category: 'achievements' }, { prompt: 'What would feel supportive right now?', category: 'self-care' }, { prompt: 'Describe a moment of calm you experienced recently.', category: 'mindfulness' }])) }, [])
  const save = async (event) => { event.preventDefault(); if (!content.trim()) return; setSaving(true); const entry = { content, mood: mood || null, tags: mood ? [mood] : [] }; try { const result = await request('/journal/entries', { method: 'POST', body: JSON.stringify(entry) }); setEntries(prev => [result, ...prev]) } catch { setEntries(prev => [{ _id: Date.now(), title: 'A new page', content, mood: mood || 'reflective', tags: mood ? [mood] : ['today'], created_at: new Date().toISOString() }, ...prev]) } finally { setContent(''); setMood(''); setSaving(false); setSaved(true); setTimeout(() => setSaved(false), 2500) } }
  return <div className="fade-up grid gap-6 xl:grid-cols-[1.1fr_.9fr]"><div><div className="panel grid-surface rounded-3xl p-6 sm:p-8"><div className="flex items-start justify-between"><div><div className="eyebrow">new reflection</div><h2 className="mt-2 text-2xl font-bold">Put it somewhere.</h2><p className="mt-2 text-sm text-[#9d91b7]">This page is only for you.</p></div><NotebookPen className="h-6 w-6 text-violet-200" /></div><form onSubmit={save} className="mt-7"><textarea className="field min-h-[210px] resize-none leading-7" value={content} onChange={e => setContent(e.target.value)} placeholder="What is moving through you today?" /><div className="mt-4 flex flex-wrap items-center gap-2"><span className="mr-2 text-xs text-[#847a99]">I feel</span>{['calm', 'anxious', 'hopeful', 'tired', 'grateful'].map(item => <button type="button" key={item} onClick={() => setMood(mood === item ? '' : item)} className={`tag transition ${mood === item ? 'border-violet-300 bg-violet-300/20 text-white' : ''}`}>{item}</button>)}</div><div className="mt-6 flex items-center justify-between"><span className="text-xs text-[#847a99]">{saved ? 'Saved. Thank you for showing up.' : '10 Calm coins for a check-in'}</span><button disabled={saving || !content.trim()} className="btn-primary disabled:cursor-not-allowed disabled:opacity-40">{saving ? 'Saving…' : 'Save reflection'} <Check className="ml-1 inline h-4 w-4" /></button></div></form></div><div className="mt-7"><SectionTitle eyebrow="your pages" title="Recent reflections" action={<span className="tag">{entries.length} pages</span>} />{entries.length === 0 ? <div className="panel rounded-2xl p-6 text-sm text-[#9d91b7]">Your first page is waiting for you.</div> : <div className="space-y-3">{entries.slice(0, 4).map(entry => <div key={entry._id || entry.id} className="panel rounded-2xl p-5"><div className="flex items-center justify-between text-xs text-[#847a99]"><span>{formatDate(entry.created_at)}</span>{entry.mood && <span className="tag">{entry.mood}</span>}</div><h3 className="mt-3 font-semibold">{entry.title || 'A quiet note'}</h3><p className="mt-2 line-clamp-2 text-sm leading-6 text-[#9d91b7]">{entry.content}</p></div>)}</div>}</div></div><div><div className="panel rounded-3xl p-6"><SectionTitle eyebrow="when words are hard" title="Try a prompt" /><div className="space-y-3">{prompts.slice(0, 4).map(prompt => <button key={prompt.prompt} onClick={() => setContent(prompt.prompt + '\n\n')} className="group w-full rounded-2xl border border-white/5 bg-[#120d20] p-4 text-left transition hover:border-violet-300/30"><span className="eyebrow text-[10px]">{prompt.category}</span><p className="mt-2 text-sm leading-6 text-[#d9cbf4]">{prompt.prompt}</p><ArrowRight className="mt-3 h-4 w-4 text-[#625477] transition group-hover:translate-x-1 group-hover:text-violet-200" /></button>)}</div></div><div className="mt-5 rounded-3xl border border-mint/10 bg-mint/[.05] p-6"><Leaf className="h-5 w-5 text-mint" /><h3 className="mt-4 font-bold">A note from your future self</h3><p className="mt-2 text-sm leading-6 text-[#a5c9b8]">You are allowed to change your mind about what a good day looks like.</p></div></div></div>
}

function formatDate(date) { return date ? new Date(date).toLocaleDateString(undefined, { month: 'short', day: 'numeric' }) : 'Today' }

function Books() {
  const [books, setBooks] = useState(demoBooks); const [mood, setMood] = useState('balanced'); const [query, setQuery] = useState(''); const [loading, setLoading] = useState(false)
  useEffect(() => { request('/books/recommend-by-mood').then(data => { if (data.books?.length) { setBooks(data.books); setMood(data.mood) } }).catch(() => {}) }, [])
  const search = async (event) => { event.preventDefault(); if (!query) return; setLoading(true); try { const data = await request(`/books/search?q=${encodeURIComponent(query)}&max_results=10`); setBooks(data.books || []) } catch { const searchTerm = query.toLowerCase(); setBooks(demoBooks.filter(book => [book.title, book.author].join(' ').toLowerCase().includes(searchTerm))) } finally { setLoading(false) } }
  return <div className="fade-up"><div className="panel grid-surface rounded-3xl p-6 sm:p-8"><div className="flex flex-col justify-between gap-5 sm:flex-row sm:items-end"><div><div className="eyebrow">picked for your {mood} mood</div><h2 className="mt-2 text-2xl font-bold">A few places to go.</h2><p className="mt-2 max-w-lg text-sm leading-6 text-[#9d91b7]">Stories can be a kind of company. These are here for the pace you need today.</p></div><form onSubmit={search} className="flex gap-2"><input className="field min-w-0 sm:w-56" value={query} onChange={e => setQuery(e.target.value)} placeholder="Search a book…" /><button className="btn-ghost px-3" aria-label="Search"><Search className="h-4 w-4" /></button></form></div></div><div className="mt-8 grid gap-4 sm:grid-cols-2 lg:grid-cols-4">{loading ? <div className="col-span-full py-16 text-center text-sm text-[#9d91b7]">Finding your next page…</div> : books.map(book => <BookCard key={book.id} book={book} />)}</div></div>
}
function BookCard({ book }) { return <article className="panel group overflow-hidden rounded-2xl"><div className="relative aspect-[4/3] overflow-hidden bg-[#211737]"><img src={book.image_url || demoBooks[0].image_url} alt="" className="h-full w-full object-cover opacity-80 transition duration-500 group-hover:scale-105 group-hover:opacity-100" /><div className="absolute inset-0 bg-gradient-to-t from-[#171127] to-transparent" /><button className="absolute bottom-3 right-3 rounded-full bg-violet-300 p-2 text-ink opacity-0 transition group-hover:opacity-100"><Plus className="h-4 w-4" /></button></div><div className="p-4"><div className="text-xs text-[#847a99]">{book.author}</div><h3 className="mt-1 line-clamp-2 font-semibold leading-5">{book.title}</h3><p className="mt-3 line-clamp-2 text-xs leading-5 text-[#9d91b7]">{book.description}</p></div></article> }

function Music() {
  const [songs, setSongs] = useState(demoSongs); const [playing, setPlaying] = useState(null); const [search, setSearch] = useState('')
  useEffect(() => { request('/songs').then(data => { if (data.songs?.length) setSongs(data.songs.slice(0, 8).map((name, i) => ({ name, artist: 'ZenHeaven radio', cover: demoSongs[i % demoSongs.length].cover, duration: '3:42', mood: 'your mix' }))) }).catch(() => {}) }, [])
  const filtered = songs.filter(song => `${song.name} ${song.artist}`.toLowerCase().includes(search.toLowerCase()))
  return <div className="fade-up"><div className="grid gap-6 lg:grid-cols-[.85fr_1.15fr]"><div className="panel grid-surface relative overflow-hidden rounded-3xl p-7 sm:p-9"><div className="absolute -right-12 -top-12 h-44 w-44 rounded-full bg-violet-300/10 blur-2xl" /><div className="eyebrow">mood radio / 01</div><h2 className="mt-3 max-w-sm text-3xl font-black leading-tight">A softer soundtrack for right now.</h2><p className="mt-4 max-w-sm text-sm leading-6 text-[#9d91b7]">Slow down without having to stop. Let the music hold the edges.</p><div className="mt-8 flex items-center gap-4"><button onClick={() => setPlaying(playing ? null : filtered[0]?.name)} className="flex h-14 w-14 items-center justify-center rounded-full bg-violet-300 text-ink shadow-lg shadow-violet-500/20">{playing ? <span className="flex gap-1"><i className="h-4 w-1 rounded bg-ink" /><i className="h-6 w-1 rounded bg-ink" /><i className="h-3 w-1 rounded bg-ink" /></span> : <Play className="ml-1 h-5 w-5 fill-current" />}</button><div><div className="text-sm font-bold">{playing || 'Press play to begin'}</div><div className="mt-1 text-xs text-[#847a99]">{playing ? 'Now playing · your mood radio' : 'A four-minute reset'}</div></div></div><div className="mt-10 flex gap-1"><span className="h-1 flex-1 rounded bg-violet-300" /><span className="h-1 w-1/4 rounded bg-violet-300/20" /></div></div><div className="panel rounded-3xl p-6"><div className="flex items-center justify-between"><div><div className="eyebrow">your listening room</div><h2 className="mt-1 text-xl font-bold">For your current pace</h2></div><div className="relative"><Search className="pointer-events-none absolute left-3 top-2.5 h-4 w-4 text-[#847a99]" /><input className="field w-36 py-2 pl-9 text-xs" value={search} onChange={e => setSearch(e.target.value)} placeholder="Find a song" /></div></div><div className="mt-5 space-y-2">{filtered.map(song => <button key={song.name} onClick={() => setPlaying(song.name)} className={`group flex w-full items-center gap-3 rounded-2xl p-2 text-left transition ${playing === song.name ? 'bg-violet-300/10' : 'hover:bg-[#211737]'}`}><img src={song.cover} alt="" className="h-11 w-11 rounded-xl object-cover" /><div className="flex-1"><div className="text-sm font-semibold">{song.name}</div><div className="mt-1 text-xs text-[#847a99]">{song.artist} · {song.mood}</div></div>{playing === song.name ? <div className="flex gap-1 text-violet-200"><i className="h-4 w-1 animate-pulse rounded bg-current" /><i className="h-6 w-1 animate-pulse rounded bg-current [animation-delay:.15s]" /><i className="h-3 w-1 animate-pulse rounded bg-current [animation-delay:.3s]" /></div> : <span className="text-xs text-[#625477]">{song.duration}</span>}<MoreHorizontal className="h-4 w-4 text-[#625477]" /></button>)}</div></div></div><div className="mt-8"><SectionTitle eyebrow="choose your energy" title="A playlist for the moment" /><div className="grid gap-4 sm:grid-cols-3"><MoodPlaylist title="Ease into it" description="Ambient warmth for slow mornings" image="https://images.unsplash.com/photo-1507525428034-b723cf961d3e?w=600" /><MoodPlaylist title="Deep focus" description="A clear desk for a busy mind" image="https://images.unsplash.com/photo-1497250681960-ef046c08a56e?w=600" /><MoodPlaylist title="Let it move" description="For when you need a little light" image="https://images.unsplash.com/photo-1500534623283-312aade485b7?w=600" /></div></div></div>
}
function MoodPlaylist({ title, description, image }) { return <div className="group relative h-36 overflow-hidden rounded-2xl border border-white/10"><img src={image} alt="" className="absolute h-full w-full object-cover opacity-45 transition duration-500 group-hover:scale-105 group-hover:opacity-65" /><div className="absolute inset-0 bg-gradient-to-t from-[#0d0a18] via-[#0d0a18]/30 to-transparent" /><div className="absolute bottom-4 left-4"><h3 className="font-bold">{title}</h3><p className="mt-1 text-xs text-[#cfc1eb]">{description}</p></div></div> }

function Therapists() {
  const [therapists, setTherapists] = useState(demoTherapists); const [filter, setFilter] = useState('All'); const [selected, setSelected] = useState(null); const [booked, setBooked] = useState(false)
  useEffect(() => { request('/therapists/').then(data => { if (data?.length) setTherapists(data) }).catch(() => {}) }, [])
  const specializations = ['All', ...new Set(therapists.flatMap(t => t.specializations || []).slice(0, 5))]
  const shown = filter === 'All' ? therapists : therapists.filter(t => t.specializations?.includes(filter))
  return <div className="fade-up"><div className="mb-6 flex flex-wrap gap-2">{specializations.map(item => <button key={item} onClick={() => setFilter(item)} className={`tag transition ${filter === item ? 'border-violet-300 bg-violet-300/20 text-white' : ''}`}>{item}</button>)}</div><div className="grid gap-5 lg:grid-cols-2">{shown.map(therapist => <article key={therapist.id || therapist._id} className="panel rounded-3xl p-5 sm:p-6"><div className="flex gap-4"><img src={therapist.photo_url || demoTherapists[0].photo_url} alt="" className="h-20 w-20 rounded-2xl object-cover" /><div className="min-w-0 flex-1"><div className="flex justify-between gap-2"><div><h2 className="font-bold">{therapist.name}</h2><div className="mt-1 flex items-center gap-1 text-xs text-[#e8c777]"><Star className="h-3 w-3 fill-current" /> {therapist.rating} <span className="ml-1 text-[#847a99]">· {therapist.experience_years} years</span></div></div><span className="text-sm font-bold text-mint">${therapist.hourly_rate}<span className="text-[10px] font-normal text-[#847a99]">/hr</span></span></div><p className="mt-3 line-clamp-2 text-sm leading-6 text-[#9d91b7]">{therapist.bio}</p></div></div><div className="mt-5 flex flex-wrap gap-2">{(therapist.specializations || []).map(s => <span className="tag" key={s}>{s}</span>)}</div><div className="mt-5 flex items-center justify-between border-t border-white/[.07] pt-4"><div className="text-xs text-[#847a99]"><Clock3 className="mr-1 inline h-3.5 w-3.5" /> Next opening · tomorrow</div><button className="btn-primary py-2 text-xs" onClick={() => { setSelected(therapist); setBooked(false) }}>View availability <ArrowRight className="ml-1 inline h-3 w-3" /></button></div></article>)}</div>{selected && <Modal onClose={() => setSelected(null)}><div className="eyebrow">book a session</div><h2 className="mt-2 text-2xl font-bold">{selected.name}</h2><p className="mt-2 text-sm leading-6 text-[#9d91b7]">Choose a time that gives you room to arrive.</p><div className="mt-6 grid grid-cols-2 gap-2"><button className="rounded-xl border border-violet-300 bg-violet-300/15 p-3 text-left text-sm"><div className="font-semibold">Tomorrow</div><div className="mt-1 text-xs text-[#9d91b7]">Sep 06</div></button><button className="rounded-xl border border-[#3a2b57] p-3 text-left text-sm"><div className="font-semibold">Monday</div><div className="mt-1 text-xs text-[#9d91b7]">Sep 07</div></button></div><div className="mt-4 grid grid-cols-3 gap-2">{['09:00 AM', '11:30 AM', '04:00 PM'].map(time => <button key={time} className="rounded-xl border border-[#3a2b57] p-3 text-xs hover:border-violet-300">{time}</button>)}</div>{booked ? <div className="mt-6 rounded-xl bg-mint/10 p-4 text-sm text-mint"><Check className="mr-2 inline h-4 w-4" /> Session request sent. We will confirm shortly.</div> : <button className="btn-primary mt-6 w-full" onClick={async () => { try { await request('/therapists/appointments', { method: 'POST', body: JSON.stringify({ therapist_id: selected.id, user_id: 'current', date: '2026-09-06T09:00:00', start_time: '2026-09-06T09:00:00', end_time: '2026-09-06T10:00:00' }) }) } catch { /* demo mode */ } setBooked(true) }}>Request this time · ${selected.hourly_rate}</button>}</Modal>}</div>
}
function Modal({ children, onClose }) { return <div className="fixed inset-0 z-50 flex items-center justify-center bg-[#08050f]/80 p-5 backdrop-blur-sm"><div className="panel relative w-full max-w-md rounded-3xl p-6 sm:p-8"><IconButton label="Close" onClick={onClose}><X /></IconButton><div className="absolute right-5 top-5" />{children}</div></div> }

function Coins() {
  const [balance, setBalance] = useState(120); const [transactions, setTransactions] = useState([]); const [goals, setGoals] = useState([])
  useEffect(() => { request('/coins/balance').then(data => setBalance(data.balance)).catch(() => {}); request('/coins/transactions').then(setTransactions).catch(() => setTransactions([{ amount: 10, transaction_type: 'earn', source: 'journal', description: 'Created a new journal entry', timestamp: new Date().toISOString() }, { amount: 5, transaction_type: 'earn', source: 'mental_health_chat', description: 'Checked in with Calm', timestamp: new Date(Date.now() - 86400000).toISOString() }])); request('/coins/daily-goals').then(setGoals).catch(() => setGoals([{ title: 'Chat with AI Therapist', current: 1, target: 1, coins: 10, completed: true }, { title: 'Write in Journal', current: 0, target: 1, coins: 15, completed: false }, { title: 'Complete Mood Check', current: 0, target: 1, coins: 5, completed: false }])) }, [])
  return <div className="fade-up"><div className="grid gap-5 lg:grid-cols-[.9fr_1.1fr]"><div className="relative overflow-hidden rounded-3xl bg-gradient-to-br from-[#bd93ff] to-[#6840a5] p-7 text-ink"><div className="absolute -right-10 -top-12 h-44 w-44 rounded-full border-[20px] border-white/15" /><div className="relative"><div className="flex items-center gap-2 text-xs font-bold uppercase tracking-[.16em]"><CircleDollarSign className="h-4 w-4" /> your balance</div><div className="mt-8 text-6xl font-black tracking-[-.06em]">{balance}</div><div className="mt-2 text-sm font-semibold text-[#2f1b52]">Calm coins</div><div className="mt-10 flex items-center justify-between border-t border-black/10 pt-4 text-xs font-semibold"><span>Keep showing up for yourself.</span><Zap className="h-4 w-4" /></div></div></div><div className="panel rounded-3xl p-6"><SectionTitle eyebrow="today's gentle goals" title="Earn by caring for yourself" /><div className="space-y-4">{goals.map((goal, index) => <div key={goal.id || index} className="flex items-center gap-3"><div className={`flex h-9 w-9 items-center justify-center rounded-xl ${goal.completed ? 'bg-mint/10 text-mint' : 'bg-violet-300/10 text-violet-200'}`}>{goal.completed ? <Check className="h-4 w-4" /> : <span className="text-sm font-bold">{index + 1}</span>}</div><div className="flex-1"><div className="flex justify-between text-sm"><span className={goal.completed ? 'text-[#847a99] line-through' : 'font-semibold'}>{goal.title}</span><span className="text-xs text-[#e8c777]">+{goal.coins}</span></div><div className="mt-2 h-1.5 overflow-hidden rounded-full bg-[#2a1d43]"><div className="h-full rounded-full bg-violet-300" style={{ width: `${Math.min(100, ((goal.current || 0) / goal.target) * 100)}%` }} /></div></div></div>)}</div></div></div><div className="mt-8 grid gap-6 lg:grid-cols-[1.1fr_.9fr]"><div className="panel rounded-3xl p-6"><SectionTitle eyebrow="where they came from" title="Recent activity" />{transactions.length === 0 ? <p className="text-sm text-[#9d91b7]">Your first calm coin is waiting around the corner.</p> : <div className="space-y-2">{transactions.slice(0, 6).map((transaction, index) => <div key={transaction._id || index} className="flex items-center gap-3 rounded-2xl bg-[#120d20] p-3"><div className="rounded-xl bg-mint/10 p-2 text-mint"><Sparkles className="h-4 w-4" /></div><div className="flex-1"><div className="text-sm font-semibold">{transaction.description}</div><div className="mt-1 text-xs text-[#847a99]">{formatDate(transaction.timestamp)}</div></div><span className="text-sm font-bold text-mint">+{transaction.amount}</span></div>)}</div>}</div><div className="panel rounded-3xl p-6"><SectionTitle eyebrow="your momentum" title="Keep the thread" /><div className="flex items-center justify-center py-5"><div className="relative flex h-40 w-40 items-center justify-center rounded-full border-[10px] border-violet-300/20"><div className="absolute inset-[-10px] rounded-full border-[10px] border-transparent border-l-violet-300 border-t-violet-300" /><div className="text-center"><div className="text-4xl font-black">4</div><div className="text-xs text-[#9d91b7]">day streak</div></div></div></div><p className="text-center text-sm leading-6 text-[#9d91b7]">You’ve been making small, meaningful space for yourself.</p></div></div></div>
}

export default function App() {
  const [user, setUser] = useState(() => JSON.parse(localStorage.getItem('zen-user') || 'null'))
  return <Routes><Route path="/" element={user ? <Navigate to="/dashboard" replace /> : <Landing />} /><Route path="/login" element={user ? <Navigate to="/dashboard" replace /> : <AuthPage onAuth={setUser} />} /><Route path="/register" element={user ? <Navigate to="/dashboard" replace /> : <AuthPage register onAuth={setUser} />} /><Route path="/dashboard" element={<Protected user={user}><Dashboard user={user} /></Protected>} /><Route path="/chat" element={<Protected user={user}><Chat /></Protected>} /><Route path="/journal" element={<Protected user={user}><Journal /></Protected>} /><Route path="/books" element={<Protected user={user}><Books /></Protected>} /><Route path="/music" element={<Protected user={user}><Music /></Protected>} /><Route path="/therapists" element={<Protected user={user}><Therapists /></Protected>} /><Route path="/coins" element={<Protected user={user}><Coins /></Protected>} /><Route path="*" element={<Navigate to={user ? '/dashboard' : '/'} replace />} /></Routes>
}
